/*
 * Parse JSON object serialization format (RFC-7159)
 */

#ifndef TEST
#include "file.h"

#ifndef lint
FILE_RCSID("@(#)$File: is_json.c,v 1.27 2022/09/16 14:15:29 christos Exp $")
#endif

#include "magic.h"
#else
#include <stdio.h>
#include <stddef.h>
#endif
#include <string.h>

#ifdef DEBUG
#include <stdio.h>
#define DPRINTF(a, b, c)        \
    printf("%*s%s [%.2x/%c] %.*s\n", (int)lvl, "", (a), *(b), *(b), \
        (int)(b - c), (const char *)(c))
#define __file_debugused
#else
#define DPRINTF(a, b, c)        do { } while (/*CONSTCOND*/0)
#define __file_debugused __attribute__((__unused__))
#endif

#define JSON_ARRAY      0
#define JSON_CONSTANT   1
#define JSON_NUMBER     2
#define JSON_OBJECT     3
#define JSON_STRING     4
#define JSON_ARRAYN     5
#define JSON_MAX        6

/*
 * if JSON_COUNT != 0:
 *      count all the objects, require that we have the whole data file
 * otherwise:
 *      stop if we find an object or an array
 */
#ifndef JSON_COUNT
#define JSON_COUNT 0
#endif

static int json_parse(const unsigned char **, const unsigned char *, size_t *,
        size_t);

static int
json_isspace(const unsigned char uc)
{
        switch (uc) {
        case ' ':
        case '\n':
        case '\r':
        case '\t':
                return 1;
        default:
                return 0;
        }
}

static int
json_isdigit(unsigned char uc)
{
        switch (uc) {
        case '0': case '1': case '2': case '3': case '4':
        case '5': case '6': case '7': case '8': case '9':
                return 1;
        default:
                return 0;
        }
}

static int
json_isxdigit(unsigned char uc)
{
        if (json_isdigit(uc))
                return 1;
        switch (uc) {
        case 'a': case 'b': case 'c': case 'd': case 'e': case 'f':
        case 'A': case 'B': case 'C': case 'D': case 'E': case 'F':
                return 1;
        default:
                return 0;
        }
}

static const unsigned char *
json_skip_space(const unsigned char *uc, const unsigned char *ue)
{
        while (uc < ue && json_isspace(*uc))
                uc++;
        return uc;
}

/*ARGSUSED*/
static int
json_parse_string(const unsigned char **ucp, const unsigned char *ue,
    size_t lvl __file_debugused)
{
        const unsigned char *uc = *ucp;
        size_t i;

        DPRINTF("Parse string: ", uc, *ucp);
        while (uc < ue) {
                switch (*uc++) {
                case '\0':
                        goto out;
                case '\\':
                        if (uc == ue)
                                goto out;
                        switch (*uc++) {
                        case '\0':
                                goto out;
                        case '"':
                        case '\\':
                        case '/':
                        case 'b':
                        case 'f':
                        case 'n':
                        case 'r':
                        case 't':
                                continue;
                        case 'u':
                                if (ue - uc < 4) {
                                        uc = ue;
                                        goto out;
                                }
                                for (i = 0; i < 4; i++)
                                        if (!json_isxdigit(*uc++))
                                                goto out;
                                continue;
                        default:
                                goto out;
                        }
                case '"':
                        DPRINTF("Good string: ", uc, *ucp);
                        *ucp = uc;
                        return 1;
                default:
                        continue;
                }
        }
out:
        DPRINTF("Bad string: ", uc, *ucp);
        *ucp = uc;
        return 0;
}

static int
json_parse_array(const unsigned char **ucp, const unsigned char *ue,
        size_t *st, size_t lvl)
{
        const unsigned char *uc = *ucp;

        DPRINTF("Parse array: ", uc, *ucp);
        while (uc < ue) {
                uc = json_skip_space(uc, ue);
                if (uc == ue)
                        goto out;
                if (*uc == ']')
                        goto done;
                if (!json_parse(&uc, ue, st, lvl + 1))
                        goto out;
